from pathlib import Path
import hashlib,json,math
import numpy as np,pandas as pd
R=next(p for p in Path(__file__).resolve().parents if (p/'transport').is_dir() and(p/'model').is_dir());D=R/'model/cycle07_scale_hierarchy/intrinsic_centrality_classes_v1/output_source477_v2';out=Path(__file__).parent
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
rec=json.loads((D/'receipt.json').read_text());source=json.loads((R/'model_inputs_cycle07/cycle07_source_mass_pool_admitted_handoff.json').read_text());n=pd.read_parquet(R/source['paths']['all173864_provider_eligibility'],columns=['id','eligible_source_provider','documented_external_context_anchor','region','own_positive_mass']);n=n[n.eligible_source_provider.fillna(False)].sort_values('id').reset_index(drop=True);ordinary=n[~n.documented_external_context_anchor.fillna(False)].reset_index(drop=True);assert len(ordinary)==26691;assert set(n[n.documented_external_context_anchor.fillna(False)].id)=={'ctx:RU-FED-MOW','ctx:RU-FED-SPB'};x=np.log(ordinary.own_positive_mass.to_numpy(float));regions=sorted(ordinary.region.astype(str).unique());codes=np.array([regions.index(r) for r in ordinary.region.astype(str)]);checks=0

def verify_curve(c,w):
 global checks
 c=c.sort_values('K');assert list(c.K)==list(range(1,11));fit={}
 for r in c.itertuples():
  means=np.array(json.loads(r.centroid_logMi_json));assert len(means)==r.K and np.isfinite(means).all() and(np.diff(means)>0).all();edges=(means[1:]+means[:-1])/2;labels=(x[:,None]>edges).sum(axis=1);objective=float(np.dot(w,(x-means[labels])**2));assert math.isclose(objective,r.sse,rel_tol=1e-12,abs_tol=1e-9);assert np.array_equal(np.bincount(labels[w>0],minlength=r.K),r.positive_provider_class_counts);fit[r.K]=(labels,edges);checks+=3
 y=c.sse.to_numpy()/c.sse.iloc[0];k=np.arange(1,11);line=np.interp(k,[1,10],[y[0],y[-1]]);g=line-y;selected=next(i for i in range(1,9) if g[i]>=max(g[1:9])-1e-12)+1;Z=np.column_stack([np.ones(10),k]);single=np.sum((y-Z@np.linalg.lstsq(Z,y,rcond=None)[0])**2);X=np.column_stack([Z,np.maximum(k-selected,0)]);b=np.linalg.lstsq(X,y,rcond=None)[0];hinge=np.sum((y-X@b)**2);gain=1-hinge/single;valid=(np.diff(y)<=1e-9).all() and g[selected-1]>=.1 and gain>=.25 and b[1]<0 and b[2]>0 and abs(b[1]+b[2])<abs(b[1]) and min(c.iloc[selected-1].positive_provider_class_counts)>=10;assert valid;checks+=2
 return selected,fit,gain

def ari(a,b):
 z=np.zeros((max(a)+1,max(b)+1),dtype=np.int64)
 for i,j in zip(a,b):z[i,j]+=1
 comb=lambda v:np.sum(v*(v-1)/2);pairs=len(a)*(len(a)-1)/2;A=comb(z.sum(axis=1));B=comb(z.sum(axis=0));expected=A*B/pairs;den=(A+B)/2-expected;return float((comb(z)-expected)/den) if den else 1.
base=pd.read_parquet(D/'baseline_allK_scree.parquet');K,basefit,gain=verify_curve(base,np.ones(len(x)));assert K==rec['baseline_elbow']['K']==3;assert math.isclose(gain,rec['baseline_elbow']['relative_gain'],abs_tol=1e-12);boot=pd.read_parquet(D/'all50_region_stability.parquet');curves=pd.read_parquet(D/'all500_replicate_K_curves.parquet');assert list(boot.replicate_id)==list(range(50));rng=np.random.default_rng(20261021);scores=[];bounds=[]
for row in boot.itertuples():
 draw=rng.multinomial(len(regions),np.full(len(regions),1/len(regions)));assert np.array_equal(draw,np.array(json.loads(row.region_weights_json)));w=draw[codes];positive=w>0;k,fit,gain=verify_curve(curves[curves.replicate_id.eq(row.replicate_id)],w);assert k==row.K==K and row.same_baseline_K and row.n_positive_weight_providers==int(positive.sum());score=ari(basefit[K][0][positive],fit[k][0][positive]);assert math.isclose(score,row.ari_positive_weight_providers,abs_tol=1e-12);assert math.isclose(gain,row.relative_gain,abs_tol=1e-12);scores.append(score);bounds.append(fit[k][1]);checks+=5
quant=(np.quantile(bounds,.75,axis=0)-np.quantile(bounds,.25,axis=0))/np.ptp(x);assert np.allclose(quant,rec['boundary_IQR_fraction_logrange'],rtol=0,atol=1e-12);assert math.isclose(float(np.median(scores)),rec['median_ARI'],abs_tol=1e-12);assert math.isclose(float(np.quantile(scores,.1)),rec['p10_ARI'],abs_tol=1e-12);assert rec['accepted_stable_classes'] and len(scores)>=40 and np.median(scores)>=.8 and np.quantile(scores,.1)>=.6 and(quant<=.15).all();checks+=4
classes=pd.read_parquet(D/'all_eligible_source_provider_classes.parquet');actual=classes.loc[classes.intrinsic_class_scope.eq('ordinary_eligible_source_provider')].sort_values('id').reset_index(drop=True);assert actual.id.equals(ordinary.id);assert np.array_equal(actual.own_positive_mass.to_numpy(),ordinary.own_positive_mass.to_numpy());assert np.array_equal(actual.intrinsic_centrality_class.to_numpy(int),basefit[K][0]);assert classes.functional_order_status.eq('UNASSIGNED').all();external=classes[classes.id.str.startswith('ctx:')];assert len(external)==2 and external.intrinsic_centrality_class.isna().all();checks+=5
registry=pd.read_parquet(R/'model/cycle07_scale_hierarchy/empirical_registry_source477_v1/all_empirical_raw_units.parquet',columns=['unit_id','empirical_level','core_id']);cross=pd.read_parquet(D/'existing_resolution_unit_focal_class_crosswalk.parquet');expect=registry.merge(classes[['id','intrinsic_centrality_class','intrinsic_class_scope','class_status']],left_on='core_id',right_on='id',how='left',validate='many_to_one');pd.testing.assert_frame_equal(expect,cross);checks+=1
for name,h in rec['files'].items():assert sha(D/name)==h;checks+=1
result={'status':'ACCEPTED_SOURCE_ONLY_ENGINEERING_CENTRALITY_CLASSES_NUMERIC_WITNESSES','all_checks_passed':True,'independent_checks':checks,'producer_not_imported':True,'source_ordinary_providers':len(ordinary),'unfitted_external_contexts':2,'source_classes':K,'spectra_independently_reconstructed':510,'replicate_draws_and_contingency_ARI':50,'median_ARI':float(np.median(scores)),'p10_ARI':float(np.quantile(scores,.1)),'receipt_sha256':sha(D/'receipt.json'),'review_code_sha256':sha(Path(__file__)),'scope':'All saved source/centroid SSE/count/objective/selection/RNG/ARI/quantile/class/crosswalk witnesses checked. Does not claim independent global optimality of KMeans or natural functional orders. Geography and demographic types unchanged.'};(out/'audit.json').write_text(json.dumps(result,ensure_ascii=False,indent=2));print(json.dumps(result,ensure_ascii=False))
